using System;
using System.Collections.Generic;
using System.Linq;
using FOC.Domain.Battle;
using FOC.Domain.Campaign;
using FOC.Domain.Characters;
using FOC.Domain.Common;
using FOC.Domain.Military;
using FOC.Domain.Random;
using FOC.Domain.Soldiers;
using FOC.Domain.Time;

namespace FOC.Application.Battle
{
    public sealed class BattleSidePlan
    {public BattleSidePlan(BattleSideId sideId,CharacterId commanderId,IEnumerable<ArmyId> armies){if(!sideId.IsValid||!commanderId.IsValid)throw new ArgumentException("Battle side plan is invalid.");SideId=sideId;CommanderId=commanderId;ArmyIds=(armies??throw new ArgumentNullException(nameof(armies))).Distinct().OrderBy(x=>x).ToList();if(ArmyIds.Count==0||ArmyIds.Any(x=>!x.IsValid))throw new ArgumentException("Battle side needs valid Armies.");}public BattleSideId SideId{get;}public CharacterId CommanderId{get;}public IReadOnlyList<ArmyId> ArmyIds{get;}}
    public sealed class BattleCreationRequest
    {public BattleCreationRequest(BattleId battleId,WorldTimestamp startedAt,RandomState randomState,IEnumerable<BattleSidePlan> sides,BattleSectorGraph sectors,BattleAmmunitionState? ammunition=null){if(!battleId.IsValid)throw new ArgumentException(nameof(battleId));BattleId=battleId;StartedAt=startedAt;RandomState=randomState;Sides=(sides??throw new ArgumentNullException(nameof(sides))).OrderBy(x=>x.SideId).ToList();Sectors=sectors??throw new ArgumentNullException(nameof(sectors));Ammunition=ammunition??new BattleAmmunitionState();}public BattleId BattleId{get;}public WorldTimestamp StartedAt{get;}public RandomState RandomState{get;}public IReadOnlyList<BattleSidePlan> Sides{get;}public BattleSectorGraph Sectors{get;}public BattleAmmunitionState Ammunition{get;}}

    public sealed class BattleCreationService
    {
        private readonly CampaignRuntimeState _campaign;public BattleCreationService(CampaignRuntimeState campaign){_campaign=campaign??throw new ArgumentNullException(nameof(campaign));}
        public BattleState Create(BattleCreationRequest request)
        {
            if(request==null)throw new ArgumentNullException(nameof(request));if(_campaign.Battles.Battles.Contains(request.BattleId))throw new InvalidOperationException("BattleId already exists.");if(!request.StartedAt.Equals(_campaign.Clock.Now))throw new InvalidOperationException("Battle must start at the current campaign timestamp.");if(request.Sides.Count<2||request.Sides.Select(x=>x.SideId).Distinct().Count()!=request.Sides.Count)throw new InvalidOperationException("Battle needs distinct sides.");var armyIds=request.Sides.SelectMany(x=>x.ArmyIds).ToList();if(armyIds.Distinct().Count()!=armyIds.Count)throw new InvalidOperationException("An Army cannot join multiple battle sides.");var sides=new List<BattleSideState>();foreach(var plan in request.Sides){RequireAvailableCharacter(plan.CommanderId);var participants=new List<BattleParticipantSnapshot>();foreach(var armyId in plan.ArmyIds)participants.Add(SnapshotArmy(_campaign.Military.Armies.GetRequired(armyId)));if(!participants.Any(x=>x.CommanderId.Equals(plan.CommanderId)))throw new InvalidOperationException("Side commander must command a participating Army.");sides.Add(new BattleSideState(plan.SideId,plan.CommanderId,participants));}foreach(var sector in request.Sectors.OrderedSectors)foreach(var eligible in sector.OrderedEligibleSides)if(!sides.Any(x=>x.Id.Equals(eligible)))throw new InvalidOperationException("Sector eligibility references a missing side.");var battle=new BattleState(request.BattleId,request.StartedAt,request.RandomState,sides,request.Sectors,request.Ammunition);new BattleInvariantValidator().ValidateOrThrow(_campaign,battle);_campaign.Battles.Battles.Add(battle);return battle;
        }
        private BattleParticipantSnapshot SnapshotArmy(ArmyState army){if(army.Lifecycle!=ArmyLifecycle.Active||army.Commander==null)throw new InvalidOperationException("Battle participant Army must be active and commanded.");RequireAvailableCharacter(army.Commander.CharacterId);var units=new List<BattleUnitSnapshot>();foreach(var unit in army.OrderedUnits){if(unit.CommanderId.HasValue)RequireAvailableCharacter(unit.CommanderId.Value);var combatants=new List<BattleCombatantSnapshot>();foreach(var soldier in _campaign.Soldiers.Soldiers.OrderedSoldiers.Where(x=>x.UnitGroupId.Equals(unit.Id)&&x.Lifecycle==SoldierLifecycle.Active)){var ids=soldier.Loadout.OrderedWeapons.Select(x=>x.EquipmentId).Concat(soldier.Loadout.OrderedArmor.Select(x=>x.EquipmentId)).ToList();if(soldier.Loadout.Shield.HasValue)ids.Add(soldier.Loadout.Shield.Value);if(soldier.Loadout.Mount.HasValue)ids.Add(soldier.Loadout.Mount.Value);foreach(var id in ids)_campaign.Soldiers.Equipment.GetRequired(id);combatants.Add(new BattleCombatantSnapshot(soldier.Id,soldier.UnitGroupId,soldier.TroopDefinitionId,soldier.CombatRoleId,ids,soldier.Loadout.Mount.HasValue));}units.Add(new BattleUnitSnapshot(army.Id,unit.Id,unit.CommanderId,unit.Headcount,combatants,unit.Morale.Assessment,unit.Fatigue.Assessment,unit.Discipline.Assessment));}var supply=army.Supply.OrderedGoods.Select(x=>new KeyValuePair<TradeGoodId,long>(x.GoodId,x.Quantity.Value));return new BattleParticipantSnapshot(army.Id,army.Commander.CharacterId,units,supply);}
        private CharacterState RequireAvailableCharacter(CharacterId id){var character=_campaign.Characters.GetRequired(id);if(character.IsDead||character.Captivity!=null)throw new InvalidOperationException("Dead or captive Character cannot participate in battle command.");return character;}
    }

    public sealed class BattleCombatService
    {
        private readonly CampaignRuntimeState _campaign;public BattleCombatService(CampaignRuntimeState campaign){_campaign=campaign??throw new ArgumentNullException(nameof(campaign));}
        public BattleCombatOutcome Resolve(BattleId battleId,BattleAttackIntent intent,IBattleCombatResolver resolver,IBattleAmmunitionPolicy ammunitionPolicy,IBattleArmorPolicy? armorPolicy=null)
        {
            if(intent==null||resolver==null||ammunitionPolicy==null)throw new ArgumentNullException();var battle=_campaign.Battles.Battles.GetRequired(battleId);if(battle.Lifecycle!=BattleLifecycle.Active)throw new InvalidOperationException("Combat requires an active battle.");var attacker=battle.RequireCombatant(intent.Attacker);var target=battle.RequireCombatant(intent.Target);var attackerDeployment=battle.GetDeployment(intent.AttackerGroup);if(!attackerDeployment.UnitGroupId.Equals(attacker.UnitGroupId))throw new InvalidOperationException("Attacker does not belong to the declared deployment group.");var targetDeployment=battle.OrderedDeployments.SingleOrDefault(x=>x.UnitGroupId.Equals(target.UnitGroupId));if(targetDeployment==null||targetDeployment.SideId.Equals(attackerDeployment.SideId))throw new InvalidOperationException("Attack target must belong to a hostile deployed group.");if(!attacker.OrderedEquipment.Contains(intent.Weapon))throw new InvalidOperationException("Attack weapon is not in the persistent loadout snapshot.");var instance=_campaign.Soldiers.Equipment.GetRequired(intent.Weapon);if(instance.Definition.Kind!=EquipmentKind.Weapon)throw new InvalidOperationException("Attack equipment is not a weapon.");var weapon=_campaign.Soldiers.Definitions.GetRequired(WeaponDefinitionId.Create(instance.Definition.Id));if(!weapon.AttackOptions.Any(x=>x.Mode==intent.AttackMode&&x.DamageType==intent.DamageType))throw new InvalidOperationException("Weapon does not expose the requested attack capability.");if(weapon.IsRanged){var required=ammunitionPolicy.RequiredUnits(intent,weapon);if(required<=0||!weapon.AmmoFamilyId.HasValue||battle.Ammunition.QuantityOf(intent.Attacker,weapon.AmmoFamilyId.Value)<required)throw new InvalidOperationException("Ranged attack lacks explicit valid ammunition consumption.");battle.Ammunition.Consume(intent.Attacker,weapon.AmmoFamilyId.Value,required);}var armor=target.OrderedEquipment.Select(x=>_campaign.Soldiers.Equipment.GetRequired(x)).Where(x=>x.Definition.Kind==EquipmentKind.Armor).Select(x=>_campaign.Soldiers.Definitions.GetRequired(ArmorDefinitionId.Create(x.Definition.Id))).ToList();var random=new SeededRandomSource(battle.RandomState);var outcome=armorPolicy==null?resolver.Resolve(battle,intent,random):armorPolicy.Resolve(battle,intent,weapon,armor,random);battle.Record(outcome,random.CaptureState());return outcome;
        }
    }

    public sealed class BattleInvariantValidator
    {
        public void ValidateOrThrow(CampaignRuntimeState campaign,BattleState battle)
        {
            if(campaign==null||battle==null)throw new ArgumentNullException();var armies=new HashSet<ArmyId>();var units=new HashSet<UnitGroupId>();var soldiers=new HashSet<SoldierId>();foreach(var side in battle.OrderedSides){var commander=campaign.Characters.GetRequired(side.CommanderId);if(commander.IsDead||commander.Captivity!=null)throw new InvalidOperationException("Battle side commander is unavailable.");foreach(var participant in side.OrderedParticipants){if(!armies.Add(participant.ArmyId))throw new InvalidOperationException("Army is duplicated across sides.");var army=campaign.Military.Armies.GetRequired(participant.ArmyId);if(army.Commander==null||!army.Commander.CharacterId.Equals(participant.CommanderId))throw new InvalidOperationException("Army commander snapshot is invalid.");foreach(var unit in participant.OrderedUnits){if(!units.Add(unit.UnitGroupId)||!army.GetRequiredUnit(unit.UnitGroupId).Id.Equals(unit.UnitGroupId)||unit.OrderedCombatants.Count>unit.CampaignHeadcount)throw new InvalidOperationException("Unit snapshot is invalid.");foreach(var combatant in unit.OrderedCombatants){if(!soldiers.Add(combatant.SoldierId))throw new InvalidOperationException("Soldier appears more than once.");var soldier=campaign.Soldiers.Soldiers.GetRequired(combatant.SoldierId);if(soldier.Lifecycle!=SoldierLifecycle.Active||!soldier.UnitGroupId.Equals(unit.UnitGroupId))throw new InvalidOperationException("Soldier is unavailable or belongs to another Unit Group.");var live=soldier.Loadout.OrderedWeapons.Select(x=>x.EquipmentId).Concat(soldier.Loadout.OrderedArmor.Select(x=>x.EquipmentId));if(soldier.Loadout.Shield.HasValue)live=live.Concat(new[]{soldier.Loadout.Shield.Value});if(soldier.Loadout.Mount.HasValue)live=live.Concat(new[]{soldier.Loadout.Mount.Value});if(!live.OrderBy(x=>x).SequenceEqual(combatant.OrderedEquipment))throw new InvalidOperationException("Battle snapshot rerolled or changed Soldier equipment.");foreach(var id in combatant.OrderedEquipment)campaign.Soldiers.Equipment.GetRequired(id);}}}}foreach(var deployment in battle.OrderedDeployments){if(!units.Contains(deployment.UnitGroupId)||!battle.GetSide(deployment.SideId).ContainsArmy(deployment.ArmyId))throw new InvalidOperationException("Deployment reference is invalid.");battle.Sectors.GetRequired(deployment.SectorId);}foreach(var allocation in battle.Ammunition.OrderedAllocations)if(!soldiers.Contains(allocation.SoldierId))throw new InvalidOperationException("Ammunition references a non-participant Soldier.");
        }
    }

    public sealed class BattleReconciliationService
    {
        private readonly CampaignRuntimeState _campaign;private readonly ICharacterDeathPolicy _deathPolicy;public BattleReconciliationService(CampaignRuntimeState campaign,ICharacterDeathPolicy? deathPolicy=null){_campaign=campaign??throw new ArgumentNullException(nameof(campaign));_deathPolicy=deathPolicy??new ImportanceStoryGuardDeathPolicy();}
        public void Apply(BattleId battleId)
        {
            var battle=_campaign.Battles.Battles.GetRequired(battleId);if(battle.Lifecycle!=BattleLifecycle.Completed||battle.Result==null||battle.IsReconciled)throw new InvalidOperationException("Battle result is unavailable or already reconciled.");if(!battle.Result.CompletedAt.Equals(_campaign.Clock.Now))throw new InvalidOperationException("Campaign clock must explicitly reach the battle completion timestamp before reconciliation.");var result=battle.Result;var snapshotUnits=battle.OrderedSides.SelectMany(x=>x.OrderedParticipants).SelectMany(x=>x.OrderedUnits).ToDictionary(x=>x.UnitGroupId);var unitStates=new Dictionary<UnitGroupId,UnitGroupState>();foreach(var outcome in result.OrderedUnitOutcomes){if(!snapshotUnits.TryGetValue(outcome.UnitGroupId,out var snapshot))throw new InvalidOperationException("Result references a non-participant Unit Group.");var state=_campaign.Military.Armies.GetRequired(snapshot.ArmyId).GetRequiredUnit(outcome.UnitGroupId);if(!state.CanApplyBattleLosses(outcome.AggregateLosses))throw new InvalidOperationException("Unit losses exceed campaign headcount.");unitStates.Add(outcome.UnitGroupId,state);}var soldierOutcomes=result.OrderedSoldierOutcomes.ToDictionary(x=>x.SoldierId);foreach(var outcome in result.OrderedSoldierOutcomes){var snapshot=battle.RequireCombatant(outcome.SoldierId);var soldier=_campaign.Soldiers.Soldiers.GetRequired(outcome.SoldierId);if(soldier.Lifecycle!=SoldierLifecycle.Active||!soldier.UnitGroupId.Equals(snapshot.UnitGroupId))throw new InvalidOperationException("Soldier changed or is unavailable before reconciliation.");}foreach(var unitOutcome in result.OrderedUnitOutcomes){var terminal=result.OrderedSoldierOutcomes.Count(x=>battle.RequireCombatant(x.SoldierId).UnitGroupId.Equals(unitOutcome.UnitGroupId)&&(x.Outcome==BattleCasualtyOutcome.Killed||x.Outcome==BattleCasualtyOutcome.Captured));if(terminal>unitOutcome.AggregateLosses)throw new InvalidOperationException("Identity-specific terminal losses exceed total Unit Group losses.");var remaining=unitStates[unitOutcome.UnitGroupId].Headcount-unitOutcome.AggregateLosses;var retained=_campaign.Soldiers.Soldiers.OrderedSoldiers.Count(x=>x.UnitGroupId.Equals(unitOutcome.UnitGroupId)&&x.Lifecycle!=SoldierLifecycle.Retired&&x.Lifecycle!=SoldierLifecycle.Killed&&x.Lifecycle!=SoldierLifecycle.Captured&&(!soldierOutcomes.TryGetValue(x.Id,out var so)||so.Outcome!=BattleCasualtyOutcome.Killed&&so.Outcome!=BattleCasualtyOutcome.Captured));if(retained>remaining)throw new InvalidOperationException("Reconciliation would leave more persistent Soldiers than aggregate headcount.");}var deathContexts=PreflightCharacters(battle,result);foreach(var outcome in result.OrderedCharacterOutcomes)ApplyCharacter(outcome,result.CompletedAt,deathContexts);foreach(var outcome in result.OrderedSoldierOutcomes){var soldier=_campaign.Soldiers.Soldiers.GetRequired(outcome.SoldierId);switch(outcome.Outcome){case BattleCasualtyOutcome.Survived:break;case BattleCasualtyOutcome.Wounded:soldier.ApplyBattleOutcome(SoldierLifecycle.Wounded);break;case BattleCasualtyOutcome.Killed:soldier.ApplyBattleOutcome(SoldierLifecycle.Killed);break;case BattleCasualtyOutcome.Captured:soldier.ApplyBattleOutcome(SoldierLifecycle.Captured);break;default:throw new InvalidOperationException();}}foreach(var outcome in result.OrderedUnitOutcomes){var unit=unitStates[outcome.UnitGroupId];unit.ApplyBattleLosses(outcome.AggregateLosses);unit.Morale.Set(outcome.Morale);unit.Fatigue.Set(outcome.Fatigue);unit.Discipline.Set(outcome.Discipline);}battle.MarkReconciled();
        }
        private Dictionary<CharacterId,CharacterDeathContext> PreflightCharacters(BattleState battle,BattleResult result){var contexts=new Dictionary<CharacterId,CharacterDeathContext>();var random=new SeededRandomSource(battle.RandomState);var participants=new HashSet<CharacterId>(battle.OrderedSides.Select(x=>x.CommanderId).Concat(battle.OrderedSides.SelectMany(x=>x.OrderedParticipants).Select(x=>x.CommanderId)).Concat(battle.OrderedSides.SelectMany(x=>x.OrderedParticipants).SelectMany(x=>x.OrderedUnits).Where(x=>x.CommanderId.HasValue).Select(x=>x.CommanderId!.Value)));foreach(var outcome in result.OrderedCharacterOutcomes){if(!participants.Contains(outcome.CharacterId))throw new InvalidOperationException("Character outcome references a non-participant.");var character=_campaign.Characters.GetRequired(outcome.CharacterId);if(character.IsDead||character.Captivity!=null)throw new InvalidOperationException("Character outcome references an unavailable Character.");if(outcome.Outcome==BattleCasualtyOutcome.Killed){var context=new CharacterDeathContext(CharacterDeathCause.Battle,result.CompletedAt,StationaryLocation(character,battle),"Killed in battle.");if(!_deathPolicy.Evaluate(character,context,random).Allowed)throw new InvalidOperationException("Character death policy rejected the battle outcome.");contexts.Add(character.Id,context);}else if(outcome.Outcome==BattleCasualtyOutcome.Captured){if(!outcome.CaptorId.HasValue||!outcome.CaptorArmyId.HasValue||outcome.CaptorId.Value.Equals(character.Id))throw new InvalidOperationException("Character captivity outcome is invalid.");var captor=_campaign.Characters.GetRequired(outcome.CaptorId.Value);if(captor.IsDead||captor.Captivity!=null)throw new InvalidOperationException("Captor is unavailable.");_campaign.Military.Armies.GetRequired(outcome.CaptorArmyId.Value);}else if(outcome.Outcome==BattleCasualtyOutcome.Wounded&&!outcome.InjurySeverity.HasValue)throw new InvalidOperationException("Character wound lacks explicit severity.");}return contexts;}
        private void ApplyCharacter(BattleCharacterOutcome outcome,WorldTimestamp at,IReadOnlyDictionary<CharacterId,CharacterDeathContext> deathContexts){var character=_campaign.Characters.GetRequired(outcome.CharacterId);switch(outcome.Outcome){case BattleCasualtyOutcome.Survived:break;case BattleCasualtyOutcome.Wounded:character.ApplyInjury(new InjuryState(outcome.InjurySeverity!.Value,at,null));break;case BattleCasualtyOutcome.Captured:character.Capture(new CaptivityState(outcome.CaptorId!.Value,CaptivitySite.WithArmy(outcome.CaptorArmyId!.Value)),at);VacateCommand(outcome.CharacterId);break;case BattleCasualtyOutcome.Killed:var context=deathContexts[outcome.CharacterId];character.MarkDead(new DeathState(context.OccurredAt,context.Cause,context.Summary),context.FinalLocation);VacateCommand(outcome.CharacterId);break;}}
        private void VacateCommand(CharacterId characterId){foreach(var army in _campaign.Military.Armies.OrderedArmies){if(army.Commander!=null&&army.Commander.CharacterId.Equals(characterId)){var assignment=_campaign.Organizations.GetRequired(army.Commander.OrganizationId).OrderedAssignments.Single(x=>x.Id.Equals(army.Commander.AssignmentId));if(assignment.IsActive)assignment.Complete();}army.VacateCommander(characterId);}foreach(var source in _campaign.Military.RecruitmentSources.OrderedSources)if(source.Authority.CharacterId.Equals(characterId)&&source.IsActive)source.Deactivate();}
        private static CharacterLocation StationaryLocation(CharacterState character,BattleState battle){if(character.Location.Kind!=CharacterLocationKind.Travelling&&character.Location.Kind!=CharacterLocationKind.Captivity)return character.Location;var participant=battle.OrderedSides.SelectMany(x=>x.OrderedParticipants).FirstOrDefault(x=>x.CommanderId.Equals(character.Id)||x.OrderedUnits.Any(u=>u.CommanderId.HasValue&&u.CommanderId.Value.Equals(character.Id)));if(participant==null)throw new InvalidOperationException("Battle Character has no stationary participant location.");return CharacterLocation.WithArmy(participant.ArmyId);}
    }
}
